//! Command tables extracted from the game's C source (`data/script_tables.json`).
//!
//! The JSON is generated by `tools/extract_script_tables.py`. Argument letters follow
//! `src/lvl_script_commands.c` (`command_desc`, `dk1_command_desc`): `A` string, `N` integer, `C`
//! creature, `P` player, `R` room, `S` slab, `L` location, `O` operator, `B` boolean; lower case =
//! optional, `!` = extended, `+` = repeat the previous type.
use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

const TABLES_JSON: &str = include_str!("../../../data/script_tables.json");

/// `COMMANDDESC_ARGS_COUNT` (src/lvl_script_lib.h:33).
pub const ARGS_COUNT: usize = 8;

#[derive(Debug, Deserialize)]
struct RawCmd {
    name: String,
    args: String,
    check: Option<String>,
}
/// A row of a named table; the JSON also has the C value, which is not needed here.
#[derive(Debug, Deserialize)]
struct RawNamed {
    name: String,
}
#[derive(Debug, Deserialize)]
struct RawTables {
    commands: Vec<RawCmd>,
    dk1_commands: Vec<RawCmd>,
    subfunctions: Vec<RawCmd>,
    named_tables: HashMap<String, Vec<RawNamed>>,
}

/// One row of a command table.
#[derive(Debug, Clone)]
pub struct CmdDesc {
    pub name: String,
    /// Argument letters, padded with spaces to [`ARGS_COUNT`] (short C strings are handled here).
    pub args: [u8; ARGS_COUNT],
    /// Name of the C `*_check` function, when the row has one.
    pub check: Option<String>,
}

impl CmdDesc {
    fn from_raw(r: &RawCmd) -> CmdDesc {
        let mut args = [b' '; ARGS_COUNT];
        for (i, b) in r.args.bytes().take(ARGS_COUNT).enumerate() {
            args[i] = b;
        }
        CmdDesc {
            name: r.name.clone(),
            args,
            check: r.check.clone(),
        }
    }
    /// Letter at `i`, or `0` past the end (the C string terminator).
    pub fn letter(&self, i: usize) -> u8 {
        self.args.get(i).copied().unwrap_or(0)
    }
    /// `count_required_parameters` (src/lvl_script.c:404).
    pub fn required(&self) -> usize {
        let mut n = 0;
        for &c in &self.args {
            if c.is_ascii_uppercase() {
                n += 1;
            } else if c == b'!' {
                continue;
            } else {
                break;
            }
        }
        n
    }
    /// True when the last letter group repeats (`+`).
    pub fn repeats(&self) -> bool {
        self.args.contains(&b'+')
    }
    /// Type letters in argument order with `!` and `+` removed (what the overlay indexes by).
    pub fn arg_letters(&self) -> Vec<u8> {
        self.args
            .iter()
            .copied()
            .filter(|&c| c != b' ' && c != b'!' && c != b'+' && c != 0)
            .collect()
    }
    /// Max number of declared (non-repeat) arguments.
    pub fn arity(&self) -> usize {
        self.arg_letters().len()
    }
}

/// All tables.
#[derive(Debug)]
pub struct Tables {
    pub commands: Vec<CmdDesc>,
    pub dk1: Vec<CmdDesc>,
    pub subfunctions: Vec<CmdDesc>,
    pub named: HashMap<String, Vec<String>>,
}

impl Tables {
    pub fn get() -> &'static Tables {
        static T: OnceLock<Tables> = OnceLock::new();
        T.get_or_init(|| {
            let raw: RawTables =
                serde_json::from_str(TABLES_JSON).expect("embedded script_tables.json");
            Tables {
                commands: raw.commands.iter().map(CmdDesc::from_raw).collect(),
                dk1: raw.dk1_commands.iter().map(CmdDesc::from_raw).collect(),
                subfunctions: raw.subfunctions.iter().map(CmdDesc::from_raw).collect(),
                named: raw
                    .named_tables
                    .into_iter()
                    .map(|(k, v)| {
                        (
                            k,
                            v.into_iter().map(|n| n.name.to_ascii_uppercase()).collect(),
                        )
                    })
                    .collect(),
            }
        })
    }

    /// Command table for a level-file version: `dk1_command_desc` for 0, else the full one.
    pub fn table(&self, version: i64) -> &[CmdDesc] {
        if version > 0 {
            &self.commands
        } else {
            &self.dk1
        }
    }

    /// `find_command_desc`: first row whose name equals `name` (already upper case).
    pub fn find(&self, version: i64, name: &str) -> Option<&CmdDesc> {
        self.table(version).iter().find(|c| c.name == name)
    }

    pub fn find_full(&self, name: &str) -> Option<&CmdDesc> {
        self.commands.iter().find(|c| c.name == name)
    }

    pub fn find_sub(&self, name: &str) -> Option<&CmdDesc> {
        self.subfunctions.iter().find(|c| c.name == name)
    }

    /// Named constant table (upper-cased names), e.g. `player_desc`.
    pub fn named(&self, table: &str) -> &[String] {
        self.named.get(table).map(|v| v.as_slice()).unwrap_or(&[])
    }

    pub fn is_named(&self, table: &str, name: &str) -> bool {
        self.named(table)
            .iter()
            .any(|n| n.eq_ignore_ascii_case(name))
    }
}

/// `script_is_preloaded_command` (src/lvl_script.c:185).
pub fn is_preloaded(name: &str) -> bool {
    matches!(
        name,
        "LEVEL_VERSION"
            | "NEW_TRAP_TYPE"
            | "NEW_OBJECT_TYPE"
            | "NEW_ROOM_TYPE"
            | "NEW_CREATURE_TYPE"
            | "COPY_CREATURE_TYPE"
    )
}
